class Vec:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __add__(self, other):
        return Vec(self.x + other.x, self.y + other.y)
    def __repr__(self):
        return f"Vec({self.x}, {self.y})"

print(Vec(1, 2) + Vec(3, 4))

class P:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __eq__(self, other):
        return self.x == other.x and self.y == other.y
    def __hash__(self):
        return hash((self.x, self.y))

print(P(1, 2) == P(1, 2), P(1, 2) is P(1, 2))
d = {P(1, 2): "point"}
print(P(1, 2) in d)

class Card:
    def __init__(self, rank):
        self.rank = rank
    def __lt__(self, other):
        return self.rank < other.rank
    def __repr__(self):
        return f"Card({self.rank})"

cards = [Card(7), Card(2), Card(9)]
print(sorted(cards))
print(max(cards))

class Playlist:
    def __init__(self, songs):
        self._songs = songs
    def __len__(self):
        return len(self._songs)
    def __getitem__(self, i):
        return self._songs[i]
    def __contains__(self, s):
        return s in self._songs

p = Playlist(["a", "b", "c"])
print(len(p), p[1], "c" in p, bool(Playlist([])))

class Rect:
    def __init__(self, w, h):
        self.w, self.h = w, h
    @property
    def area(self):
        return self.w * self.h

r = Rect(3, 4)
print(r.area)
r.w = 10
print(r.area)

class Person:
    def __init__(self, age):
        self.age = age            # calls the setter
    @property
    def age(self):
        return self._age
    @age.setter
    def age(self, value):
        if value < 0:
            raise ValueError("age cannot be negative")
        self._age = value

p = Person(20)
p.age = 21
print(p.age)
p.age = -1

class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
    @classmethod
    def from_string(cls, s):
        x, y = s.split(",")
        return cls(int(x), int(y))

p = Point.from_string("3,4")
print(p.x, p.y)

class Temp:
    @staticmethod
    def c_to_f(c):
        return c * 9 / 5 + 32

print(Temp.c_to_f(100))

class Book:
    def __init__(self, title, year):
        self.title, self.year = title, year
    def __lt__(self, other):
        return self.year < other.year
    def __str__(self):
        return f"{self.title} ({self.year})"

class Library:
    def __init__(self):
        self._books = []
    def add(self, book):
        self._books.append(book)
    def __len__(self):
        return len(self._books)
    @property
    def oldest(self):
        return min(self._books)

lib = Library()
lib.add(Book("Master and Margarita", 1967))
lib.add(Book("War and Peace", 1869))
print(len(lib), lib.oldest)

